DROP TABLE IF EXISTS staff;
DROP TABLE IF EXISTS sales_snapshot;
CREATE TABLE staff (staff_id INTEGER PRIMARY KEY, full_name TEXT, department TEXT, salary INTEGER);
INSERT INTO staff VALUES (1,'Asha','Sales',52000),(2,'Bilal','IT',61000),(3,'Chitra','Sales',57000);
CREATE TABLE sales_snapshot AS SELECT staff_id, full_name, salary FROM staff WHERE department='Sales';
SELECT staff_id, full_name, salary FROM sales_snapshot ORDER BY staff_id;

DROP TABLE IF EXISTS staff;
DROP TABLE IF EXISTS staff_names;
CREATE TABLE staff (staff_id INTEGER PRIMARY KEY, full_name TEXT, department TEXT, salary INTEGER);
INSERT INTO staff VALUES (1,'Asha','Sales',52000),(2,'Bilal','IT',61000);
CREATE TABLE staff_names AS SELECT full_name, department FROM staff;
SELECT full_name, department FROM staff_names ORDER BY full_name;

DROP TABLE IF EXISTS staff;
DROP TABLE IF EXISTS salary_review;
CREATE TABLE staff (staff_id INTEGER PRIMARY KEY, full_name TEXT, department TEXT, salary INTEGER);
INSERT INTO staff VALUES (1,'Asha','Sales',52000),(2,'Bilal','IT',61000);
CREATE TABLE salary_review AS SELECT full_name, salary, salary * 1.10 AS proposed_salary FROM staff;
SELECT full_name, proposed_salary FROM salary_review ORDER BY full_name;

DROP TABLE IF EXISTS staff;
DROP TABLE IF EXISTS department_totals;
CREATE TABLE staff (staff_id INTEGER PRIMARY KEY, full_name TEXT, department TEXT, salary INTEGER);
INSERT INTO staff VALUES (1,'Asha','Sales',52000),(2,'Bilal','IT',61000),(3,'Chitra','Sales',57000);
CREATE TABLE department_totals AS SELECT department, COUNT(*) AS staff_count, SUM(salary) AS payroll FROM staff GROUP BY department;
SELECT department, staff_count, payroll FROM department_totals ORDER BY department;

DROP TABLE IF EXISTS staff;
DROP TABLE IF EXISTS empty_staff_copy;
CREATE TABLE staff (staff_id INTEGER PRIMARY KEY, full_name TEXT, department TEXT, salary INTEGER);
INSERT INTO staff VALUES (1,'Asha','Sales',52000);
CREATE TABLE empty_staff_copy AS SELECT staff_id, full_name, department, salary FROM staff WHERE 0;
SELECT COUNT(*) AS copied_rows FROM empty_staff_copy;

